enum Mode {
    case saveRecoveryKey              // Initial: user should save key before logout
    case waitingToStart(hasStalled: Bool)  // Waiting for backup to start
    case backupOngoing(progress: Double)   // Upload in progress
    case offline                      // Network disconnected
