**Logout Attempt Logic** (lines 64-91):

```swift
private func attemptLogout() {
    if case .saveRecoveryKey = state.mode {
        // Transition from save to waiting state
        updateMode(backupState: backupUploadStateSubject.value, 
                   reachability: homeserverReachabilityPublisher.value)

        keyUploadWaitingTask = Task {
            // Wait for backup upload
            var result = await secureBackupController.waitForKeyBackupUpload(
                uploadStateSubject: backupUploadStateSubject)

            guard !Task.isCancelled else { return }

            if case .failure = result {
                // Retry once
                result = await secureBackupController.waitForKeyBackupUpload(
                    uploadStateSubject: backupUploadStateSubject)
            }

            guard !Task.isCancelled else { return }

            guard case .success = result else {
                state.bindings.alertInfo = .init(id: .backupUploadFailed)
                return
            }

            actionsSubject.send(.logout)  // Proceed with logout
        }
    } else {
        actionsSubject.send(.logout)  // Skip backup check
    }
}
```

**Mode Updates** (lines 93-107):

```swift
private func updateMode(backupState: SecureBackupSteadyState, 
                       reachability: NetworkMonitorReachability) {
    switch (backupState, reachability) {
    case (.waiting, .reachable):
        state.mode = .waitingToStart(hasStalled: false)
        showAsStalledAfterTimeout()  // Show stalled after 2 seconds
    case (.uploading(let uploadedKeyCount, let totalKeyCount), .reachable):
        state.mode = .backupOngoing(progress: Double(uploadedKeyCount) / Double(totalKeyCount))
    case (.done, .reachable):
        state.mode = .backupOngoing(progress: 1.0)
    case (_, .unreachable):
        state.mode = .offline
    }
}
```

